class Solution {
    private final java.util.Map<String, Integer> counts = new java.util.HashMap<>();
    private final java.util.List<TreeNode> duplicates = new java.util.ArrayList<>();

    public java.util.List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        serialize(root);
        return duplicates;
    }

    private String serialize(TreeNode node) {
        if (node == null) {
            return "#";
        }
        String signature = node.val + "," + serialize(node.left) + "," + serialize(node.right);
        int seen = counts.getOrDefault(signature, 0);
        if (seen == 1) {
            duplicates.add(node);
        }
        counts.put(signature, seen + 1);
        return signature;
    }
}

class Solution {
    private int nextId = 1;
    private final java.util.Map<Key, Integer> ids = new java.util.HashMap<>();
    private final java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
    private final java.util.List<TreeNode> duplicates = new java.util.ArrayList<>();

    public java.util.List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        getId(root);
        return duplicates;
    }

    private int getId(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int leftId = getId(node.left);
        int rightId = getId(node.right);
        Key key = new Key(node.val, leftId, rightId);
        int id = ids.computeIfAbsent(key, ignored -> nextId++);
        int seen = counts.getOrDefault(id, 0);
        if (seen == 1) {
            duplicates.add(node);
        }
        counts.put(id, seen + 1);
        return id;
    }

    private static final class Key {
        private final int value;
        private final int leftId;
        private final int rightId;

        private Key(int value, int leftId, int rightId) {
            this.value = value;
            this.leftId = leftId;
            this.rightId = rightId;
        }

        @Override
        public boolean equals(Object other) {
            if (!(other instanceof Key key)) {
                return false;
            }
            return value == key.value && leftId == key.leftId && rightId == key.rightId;
        }

        @Override
        public int hashCode() {
            return java.util.Objects.hash(value, leftId, rightId);
        }
    }
}

class Solution {
    private final java.util.List<TreeNode> duplicates = new java.util.ArrayList<>();
    private final java.util.Map<Integer, java.util.List<TreeNode>> seenByValue = new java.util.HashMap<>();
    private final java.util.Set<TreeNode> reported = java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<>());

    public java.util.List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        scan(root);
        return duplicates;
    }

    private void scan(TreeNode node) {
        if (node == null) {
            return;
        }

        java.util.List<TreeNode> bucket = seenByValue.computeIfAbsent(node.val, key -> new java.util.ArrayList<>());
        for (TreeNode previous : bucket) {
            if (sameTree(node, previous)) {
                if (!reported.contains(previous)) {
                    duplicates.add(node);
                    reported.add(previous);
                }
                bucket.add(node);
                scan(node.left);
                scan(node.right);
                return;
            }
        }

        bucket.add(node);
        scan(node.left);
        scan(node.right);
    }

    private boolean sameTree(TreeNode a, TreeNode b) {
        if (a == null || b == null) {
            return a == b;
        }
        return a.val == b.val && sameTree(a.left, b.left) && sameTree(a.right, b.right);
    }
}
